import{_ as i,a0 as a,w as p,s as r,ao as m,I as l,a1 as e,A as s,x as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"交友网站的2000万用户数据遭泄露 | LCTT x X-CMD","titleTemplate":false,"description":"交友网站的2000万用户数据遭泄露 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"交友网站的2000万用户数据遭泄露 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"交友网站的2000万用户数据遭泄露 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20150126 Data of 20 Million Users Stolen from Dating Website","title":"交友网站的2000万用户数据遭泄露","tag":"201501","desc":""},"relativePath":"201501/20150126 Data of 20 Million Users Stolen from Dating Website.md","filePath":"[post].md"}'),f={name:"201501/20150126 Data of 20 Million Users Stolen from Dating Website.md"};function u(d,t,T,g,D,C){const n=a("Link");return p(),r("div",null,[t[15]||(t[15]=m('<h1 id="交友网站的2000万用户数据遭泄露" tabindex="-1">交友网站的2000万用户数据遭泄露 <a class="header-anchor" href="#交友网站的2000万用户数据遭泄露" aria-label="Permalink to “交友网站的2000万用户数据遭泄露”">​</a></h1><p><em>泄露数据包括Gmail、Hotmail以及Yahoo邮箱</em></p><p><img src="http://i1-news.softpedia-static.com/images/news2/Data-of-20-Million-Users-Stolen-from-Dating-Website-471179-2.jpg" alt="泄露的数据很可能来自于在线交友网站Topface"></p><p>#一名黑客非法窃取了在线交友网站Topface一个包含2000万用户资料的数据库。</p><p>目前并不清楚这些数据是否已经公开，但是根据某些未公开页面的消息说，某个网名为“Mastermind”的人声称掌握着这些数据。</p><p>#泄露数据列表涵盖了全世界数百个域名</p><p>此人号称泄露数据的内容100%真实有效，而Easy Solutions的CTO，Daniel Ingevaldson 周日在一篇博客中说道，泄露数据包括Hotmail、Yahoo和Gmail等邮箱地址。</p><p>Easy Solutions是一家位于美国的公司，提供多个不同平台的网络检测与安全防护产品。</p><p>据Ingevaldson所说，泄露的数据中，700万来自于Hotmail，250万来自于Yahoo，220万来自于Gmail.com。</p><p>我们并不清楚这些数据是可以直接登录邮箱账户的用户名和密码，还是登录交友网站的账户。另外，也不清楚这些数据在数据库中是加密状态还是明文存在的。</p><p>邮箱地址常常被用于在线网站的登录用户名，用户可以凭借唯一密码进行登录。然而重复使用同一个密码是许多用户的常用作法，同一个密码可以登录许多在线账户。</p>',11)),l("p",null,[e(n,{href:"1"},{default:s(()=>[...t[0]||(t[0]=[o("Ingevaldson 还说",-1)])]),_:1}),t[1]||(t[1]=o("：“看起来，这些数据事实上涵盖了全世界数百个域名。除了原始被黑的网页，黑客和不法分子很可能利用窃取的帐密进行暴库、自动扫描、危害包括银行业、旅游业以及email提供商在内的多个网站。”",-1))]),t[16]||(t[16]=l("p",null,"#预计将披露更多信息",-1)),t[17]||(t[17]=l("p",null,"据我们的多个消息源爆料，数据的泄露源就是Topface，一个包含9000万用户的在线交友网站。其总部位于俄罗斯圣彼得堡，超过50%的用户来自于俄罗斯以外的国家。",-1)),t[18]||(t[18]=l("p",null,"我们联系了Topface，向他们求证最近是否遭受了可能导致如此大量数据泄露的网络攻击；但目前我们仍未收到该公司的回复。",-1)),t[19]||(t[19]=l("p",null,"攻击者可能无需获得非法访问权限就窃取了这些数据，Easy Solutions 推测攻击者很可能针对网站客户端使用钓鱼邮件直接获取到了用户数据。",-1)),t[20]||(t[20]=l("p",null,"我们无法通过Easy Solutions的在线网站联系到他们，但我们已经尝试了其他交互通讯方式，目前正在等待更多信息的披露。",-1)),t[21]||(t[21]=l("hr",null,null,-1)),l("p",null,[t[3]||(t[3]=o("via:",-1)),e(n,{href:"http://news.softpedia.com/news/Data-of-20-Million-Users-Stolen-from-Dating-Website-471179.shtml"},{default:s(()=>[...t[2]||(t[2]=[o("http://news.softpedia.com/news/Data-of-20-Million-Users-Stolen-from-Dating-Website-471179.shtml",-1)])]),_:1})]),t[22]||(t[22]=l("p",null,"本文发布时间:26 Jan 2015, 10:20 GMT",-1)),l("p",null,[t[5]||(t[5]=o("作者：",-1)),e(n,{href:"http://news.softpedia.com/editors/browse/ionut-ilascu"},{default:s(()=>[...t[4]||(t[4]=[o("Ionut Ilascu",-1)])]),_:1})]),l("p",null,[t[7]||(t[7]=o("译者：",-1)),e(n,{href:"https://github.com/tinyeyeser"},{default:s(()=>[...t[6]||(t[6]=[o("Mr小眼儿",-1)])]),_:1})]),l("p",null,[t[9]||(t[9]=o("校对：",-1)),e(n,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...t[8]||(t[8]=[o("Caroline",-1)])]),_:1})]),l("p",null,[t[12]||(t[12]=o("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[o("LCTT",-1)])]),_:1}),t[13]||(t[13]=o(" 原创翻译，",-1)),e(n,{href:"http://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[o("Linux中国",-1)])]),_:1}),t[14]||(t[14]=o(" 荣誉推出",-1))])])}const x=i(f,[["render",u]]);export{b as __pageData,x as default};
